// 朴素版 Dijkstra：线性扫描选最小，O(V^2 + E)
function dijkstra(graph, s) {
  const n = graph.length;
  const dist = new Array(n).fill(Infinity);
  const used = new Array(n).fill(false);
  dist[s] = 0;
  for (let k = 0; k < n; k++) {
    // 1. 选未确定节点中 dist 最小的 u
    let u = -1;
    for (let i = 0; i < n; i++)
      if (!used[i] && (u === -1 || dist[i] < dist[u])) u = i;
    if (u === -1 || dist[u] === Infinity) break; // 剩余点不可达
    used[u] = true;
    // 2. 松弛 u 的所有出边
    for (const { to, w } of graph[u]) {
      if (dist[u] + w < dist[to]) dist[to] = dist[u] + w;
    }
  }
  return dist;
}

